import json, sys

path = sys.argv[1]
maxlen = int(sys.argv[2]) if len(sys.argv) > 2 else 400

def trunc(s, n=maxlen):
    s = str(s)
    return s if len(s) <= n else s[:n] + f"...[{len(s)}chars]"

with open(path) as f:
    for line in f:
        line = line.strip()
        if not line:
            continue
        try:
            obj = json.loads(line)
        except Exception as e:
            print("PARSE ERROR", e)
            continue
        ts = obj.get("timestamp", "")
        typ = obj.get("type", obj.get("role", "?"))
        msg = obj.get("message", obj)
        role = msg.get("role", typ) if isinstance(msg, dict) else typ
        content = msg.get("content") if isinstance(msg, dict) else None
        out = [f"[{ts}] {role}"]
        if isinstance(content, str):
            out.append(trunc(content))
        elif isinstance(content, list):
            for c in content:
                if not isinstance(c, dict):
                    out.append(trunc(c))
                    continue
                ctype = c.get("type")
                if ctype == "text":
                    out.append(f"TEXT: {trunc(c.get('text',''))}")
                elif ctype == "tool_use":
                    out.append(f"TOOL_USE {c.get('name')}: {trunc(c.get('input'), 300)}")
                elif ctype == "tool_result":
                    cc = c.get("content")
                    out.append(f"TOOL_RESULT: {trunc(cc, 300)}")
                else:
                    out.append(f"{ctype}: {trunc(c, 200)}")
        print(" | ".join(out))

